#!/usr/bin/env python3
"""📬️ U6 E1 set — the paged DOCX route (generated by `wp-u6/t4/make_e1_set.py` from the pre-E1 snapshot → the proven E1 overlay).

* stdio contract: the structural one-item preparation (`StructuralPreparationFactory`, `StructuralMutationCopy`, page-sized
  copy steps) lives in `✏️editing/🏗️structural` beside `RetainedTextCopy`/`RetainedBytesCopy`; Semio mesh/brep import it
  (their private copy is removed); `snapshot_details_editor_support!` takes an optional `store_owners:` catalogue.
* docx: every addressed XML edit copies its base through `DocxStructuralCopy` (OPC payloads/metadata, then each XML part through
  an explicit-stack node walk, ≤ one page per step) and applies the mutation to the copy in one bounded final step; snapshots and
  mutations retire owner by owner (`DocxRetirementCursor`), the document store installs that catalogue; a DTD in a package part
  is refused (OPC M1.17).
* store: an O(1) undo keeps the undone state in the tail slot on the other side of the same edit (`tail_snapshot_follows`), so
  the redo of exactly that edit hands it back — no whole-snapshot clone and replay in one turn.
* laws: docx `a_five_megabyte_set_page_prepares_publishes_undoes_and_redoes_within_every_grant`; store
  `apply_undo_redo_transfers_each_snapshot_root_to_one_exact_retirement_owner` (redo reuses the kept root: 2 roots retire).

Usage: u6-e1-paged-docx.py [--dry-run | --write | --revert] [--root <repo root>]"""
import json
import sys
from pathlib import Path

ROOT = Path(sys.argv[sys.argv.index("--root") + 1]) if "--root" in sys.argv else Path("/Users/ueli/Documents/semio")
WRITE = "--write" in sys.argv
REVERT = "--revert" in sys.argv
BACKUP = Path("/Users/ueli/Documents/semio/.🧬semio/🌐hub/s14-u6-backup/e1-paged-docx")
SETS = json.loads(__SETS__)
NEWS = json.loads(__NEWS__)
REMOVED = __REMOVED__


def main() -> int:
    if REVERT:
        for rel in [*SETS, *REMOVED]:
            saved = BACKUP / rel
            if saved.exists():
                (ROOT / rel).parent.mkdir(parents=True, exist_ok=True)
                (ROOT / rel).write_bytes(saved.read_bytes())
        for rel in NEWS:
            (ROOT / rel).unlink(missing_ok=True)
        print("reverted")
        return 0
    faults, staged = [], {}
    for rel, pairs in SETS.items():
        path = ROOT / rel
        if not path.exists():
            faults.append(f"missing {rel}")
            continue
        text = path.read_text()
        for before, after in pairs:
            count = text.count(before)
            if count != 1:
                faults.append(f"anchor x{count} in {rel}: {before[:120]!r}")
                continue
            text = text.replace(before, after)
        staged[rel] = text
    for rel, text in NEWS.items():
        if (ROOT / rel).exists() and (ROOT / rel).read_text() != text:
            faults.append(f"new file already present with other content: {rel}")
        staged[rel] = text
    for rel in REMOVED:
        if not (ROOT / rel).exists():
            faults.append(f"removal target missing: {rel}")
    print(f"{len(SETS)} anchored, {len(NEWS)} new, {len(REMOVED)} removed; faults={len(faults)}")
    for fault in faults:
        print("FAULT", fault)
    if faults or not WRITE:
        return 1 if faults else 0
    for rel in [*SETS, *REMOVED]:
        source = ROOT / rel
        if source.exists():
            (BACKUP / rel).parent.mkdir(parents=True, exist_ok=True)
            (BACKUP / rel).write_bytes(source.read_bytes())
    for rel, text in staged.items():
        (ROOT / rel).parent.mkdir(parents=True, exist_ok=True)
        (ROOT / rel).write_text(text)
    for rel in REMOVED:
        (ROOT / rel).unlink()
    print("written")
    return 0


if __name__ == "__main__":
    sys.exit(main())
